import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"Android sideload (Tauri APK)","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/android-sideload.md","filePath":"desktop/android-sideload.md"}`),a={name:`desktop/android-sideload.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="android-sideload-tauri-apk" tabindex="-1">Android sideload (Tauri APK) <a class="header-anchor" href="#android-sideload-tauri-apk" aria-label="Permalink to “Android sideload (Tauri APK)”">​</a></h1><p>DocuHaim Android is a <strong>Tauri v2</strong> shell around the same SPA. It is <strong>not</strong> distributed on Google Play. Install the APK from the unified GitHub Release.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to “Releases”">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Workflow</th><th>Tag</th><th>Artifacts</th></tr></thead><tbody><tr><td>Unified (preferred)</td><td><code>.github/workflows/release-tauri.yml</code></td><td><code>vX.Y.Z</code></td><td>DMG / NSIS / <strong>per-ABI + universal</strong> APK / <code>latest.json</code></td></tr><tr><td>Android-only (optional)</td><td><code>.github/workflows/release-tauri-android.yml</code></td><td><code>vX.Y.Z</code> (same)</td><td>same debug-signed APK set (<code>make_latest: false</code>)</td></tr></tbody></table><p>Android APKs ship on the <strong>same</strong> <code>vX.Y.Z</code> release as desktop. Do <strong>not</strong> publish separate <code>android-v*</code> tags — GitHub <code>/releases/latest</code> would point at them and break desktop auto-update (<code>latest.json</code> 404).</p><p>CI builds <strong>debug-signed</strong> APKs (sideload without a release keystore):</p><ol><li><code>tauri android build --debug --apk --split-per-abi</code> → one APK per ABI</li><li><code>tauri android build --debug --apk</code> → universal APK (all ABIs)</li></ol><p>Assets are renamed by <a href="../../scripts/collect-android-release-apks.mjs"><code>scripts/collect-android-release-apks.mjs</code></a> to <code>DocuHaim_&lt;version&gt;_&lt;abi&gt;-debug.apk</code>. Release notes come from <a href="./github-release-body.html"><code>github-release-body.md</code></a>.</p><h3 id="which-apk-to-download" tabindex="-1">Which APK to download <a class="header-anchor" href="#which-apk-to-download" aria-label="Permalink to “Which APK to download”">​</a></h3><table tabindex="0"><thead><tr><th>Asset suffix</th><th>ABI</th><th>Typical devices</th></tr></thead><tbody><tr><td><code>arm64-v8a-debug.apk</code></td><td><code>arm64-v8a</code></td><td>Most phones / tablets (<strong>preferred</strong>)</td></tr><tr><td><code>armeabi-v7a-debug.apk</code></td><td><code>armeabi-v7a</code></td><td>Older 32-bit ARM</td></tr><tr><td><code>x86_64-debug.apk</code></td><td><code>x86_64</code></td><td>Many Android emulators</td></tr><tr><td><code>x86-debug.apk</code></td><td><code>x86</code></td><td>Older x86 emulators</td></tr><tr><td><code>universal-debug.apk</code></td><td>all</td><td>Any device (largest)</td></tr></tbody></table><h3 id="how-to-check-your-architecture" tabindex="-1">How to check your architecture <a class="header-anchor" href="#how-to-check-your-architecture" aria-label="Permalink to “How to check your architecture”">​</a></h3><p><strong>On device:</strong> Settings → About phone / About device → CPU / Hardware, or an app such as CPU-Z (SoC → ABI / Instruction Sets). Most modern phones are <strong><code>arm64-v8a</code></strong>.</p><p><strong>With adb:</strong></p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> getprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ro.product.cpu.abi</span></span></code></pre></div><p>Match the printed ABI to the table above. If unsure, use <strong>universal</strong>.</p><h3 id="publish-normal" tabindex="-1">Publish (normal) <a class="header-anchor" href="#publish-normal" aria-label="Permalink to “Publish (normal)”">​</a></h3><ol><li>Actions → <strong>Release Tauri</strong> → Run workflow.</li><li>Download DMG / EXE / the matching APK from the new <code>v…</code> release (also linked from <a href="https://github.com/explainpark101/DocuHaim/releases/latest" target="_blank" rel="noreferrer">releases/latest</a>).</li></ol><h3 id="publish-apk-only-rebuild" tabindex="-1">Publish APK only (rebuild) <a class="header-anchor" href="#publish-apk-only-rebuild" aria-label="Permalink to “Publish APK only (rebuild)”">​</a></h3><ol><li>Actions → <strong>Release Tauri Android</strong> → Run workflow.</li><li>Optional <code>version</code> input (defaults to root <code>package.json</code> version). Uploads to <code>vX.Y.Z</code> without changing which release is “Latest”.</li></ol><h2 id="install-sideload" tabindex="-1">Install (sideload) <a class="header-anchor" href="#install-sideload" aria-label="Permalink to “Install (sideload)”">​</a></h2><ol><li>On the phone, allow install from the browser/Files app (“unknown apps”).</li><li>Open the downloaded <code>.apk</code> for <strong>your ABI</strong> (or universal) and install.</li><li>First launch: unlock with master password and/or <strong>생체 인식</strong> (platform biometric via Stronghold — not browser WebAuthn/PRF).</li></ol><h2 id="features-on-android" tabindex="-1">Features on Android <a class="header-anchor" href="#features-on-android" aria-label="Permalink to “Features on Android”">​</a></h2><ul><li><strong>S3 / WebDAV</strong> — same encrypted credential flow; secrets in Stronghold (app-private).</li><li><strong>Local Haim</strong> — default vault under app data (<code>LocalHaim</code>). You can also pick another folder via the system dialog when available.</li><li><strong><code>.md</code> / <code>.markdown</code> file association</strong> — open markdown from Files / other apps with DocuHaim (vault note if under the Local root, otherwise session workspace).</li><li><strong>Advanced Search</strong> — filename / path / commands only; Lucivy inverted index is disabled.</li><li><strong>App version + APK auto-update</strong> — Settings → 앱 shows the native package version (<code>getVersion</code>). “최신 APK 확인” polls GitHub Releases for <code>DocuHaim_&lt;ver&gt;_&lt;abi&gt;-debug.apk</code> (falls back to universal), downloads into app cache, and opens the system installer (<code>REQUEST_INSTALL_PACKAGES</code> / unknown-apps allow).</li><li><strong>System status bar</strong> — Settings toggle (or Advanced Search) to show/hide the Android status bar over the fullscreen WebView.</li><li><strong>share_target</strong> — existing PWA share intake is assumed to keep working; this shell does not reimplement it.</li></ul><h3 id="launcher-icons" tabindex="-1">Launcher icons <a class="header-anchor" href="#launcher-icons" aria-label="Permalink to “Launcher icons”">​</a></h3><p>Adaptive icons are regenerated with a safe-zone inset via <a href="../../scripts/generate-android-icons.mjs"><code>scripts/generate-android-icons.mjs</code></a> (also run automatically by <code>tauri:android:dev</code> / <code>tauri:android:build*</code>). Do not rely on raw <code>tauri icon</code> foregrounds alone — they fill too much of the adaptive canvas and look oversized.</p><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to “Local development”">​</a></h2><p>Requires Android SDK + NDK, <strong>JDK 17</strong>, and Rust Android targets.<br><code>bun run tauri:android:*</code> uses <a href="../../scripts/tauri-android.mjs"><code>scripts/tauri-android.mjs</code></a> to set <code>JAVA_HOME</code> (Homebrew OpenJDK) so Gradle does not hit macOS’s “Unable to locate a Java Runtime” stub.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Sideload-ready (debug-signed) — recommended for device install without a release keystore</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:android:build:debug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Release APK (needs signingConfig / keystore — otherwise unsigned and will not install)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:android:build</span></span></code></pre></div><p>APK output: <code>src-tauri/gen/android/app/build/outputs/apk/</code>.<br> Project files: <code>src-tauri/gen/android/</code>. Intent filters come from <a href="../../src-tauri/tauri.conf.json"><code>src-tauri/tauri.conf.json</code></a> <code>bundle.fileAssociations</code>.</p><h2 id="signing" tabindex="-1">Signing <a class="header-anchor" href="#signing" aria-label="Permalink to “Signing”">​</a></h2><p>GitHub Release Android APKs are <strong>debug-signed</strong> (same idea as local <code>tauri:android:build:debug</code>). Plain <code>tauri:android:build</code> (release, no keystore) can produce an unsigned APK that Android rejects (“패키지가 잘못되어…”). For private release signing later, configure Gradle <code>signingConfig</code> / CI secrets and switch the workflow off <code>--debug</code>.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h2><ul><li>Google Play / AAB</li><li>iOS</li><li>Browser WebAuthn PRF in the Android WebView (platform biometric only)</li></ul>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};